const prepare = ({ body, timezone, signature }) => {
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(body.email || ""))) {
    throw new Error("A valid lead email is required before saving or notifying.");
  }
  const escapeMarkdown = (text) =>
    text
      .replace(/([\\_*[\]])/g, "\\$1")
      .replaceAll(String.fromCharCode(96), "\\" + String.fromCharCode(96));
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-GB", {
      timeZone: timezone,
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23",
    })
      .formatToParts(new Date())
      .map((part) => [part.type, part.value]),
  );
  const lead = {
    nome: String(body.nome || body.name || "Non indicato"),
    email: String(body.email || ""),
    telefono: String(body.telefono || body.phone || "Non indicato"),
    messaggio: String(body.messaggio || body.message || ""),
    data: parts.day + "/" + parts.month + "/" + parts.year + " " + parts.hour + ":" + parts.minute,
  };
  return {
    lead,
    values: [[lead.data, lead.nome, lead.email, lead.telefono, lead.messaggio, "Nuovo"]],
    alert:
      "🔔 *Nuovo lead dal sito!*\n\n👤 " +
      escapeMarkdown(lead.nome) +
      "\n📧 " +
      escapeMarkdown(lead.email) +
      "\n📞 " +
      escapeMarkdown(lead.telefono) +
      "\n\n💬 " +
      escapeMarkdown(lead.messaggio),
    email: lead.email,
    reply:
      "Ciao " +
      lead.nome +
      ",\n\ngrazie per averci contattato! Abbiamo ricevuto la tua richiesta e ti risponderemo entro poche ore lavorative.\n\nNel frattempo, se la cosa è urgente, puoi chiamarci direttamente.\n\nA presto,\n" +
      signature,
  };
};

return $input.all().map((item, index) => {
  const result = prepare({
    body: item.json.body,
    timezone: $now.zoneName,
    signature: "[IL TUO NOME / AZIENDA]",
  });
  return {
    json: { ...result.lead, alert: result.alert, reply: result.reply },
    pairedItem: { item: index },
  };
});
